import { Router, type Request, type Response } from "express";
import {
  getAllDonors,
  getDonorById,
  insertDonor,
  updateDonor,
  deleteDonor
} from "../db/donors-table";
import {
  insertSearchResult,
  getRecentSearches
} from "../db/search-results-table";

export const router = Router();

// Get all donors
router.get("/donors", (req: Request, res: Response) => {
  try {
    const donors = getAllDonors();
    res.json(donors);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch donors" });
  }
});

// Get a donor by ID
router.get("/donors/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donor ID" });
    }

    const donor = getDonorById(id);
    if (!donor) {
      return res.status(404).json({ error: "Donor not found" });
    }

    res.json(donor);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch donor" });
  }
});

// Create a new donor
router.post("/donors", (req: Request, res: Response) => {
  try {
    const { name, contact, blood_group } = req.body;

    if (!name || !contact || !blood_group) {
      return res.status(400).json({ error: "Name, contact, and blood group are required" });
    }

    const newDonor = {
      name,
      contact,
      blood_group
    };

    const id = insertDonor(newDonor);
    const createdDonor = getDonorById(id);

    if (!createdDonor) {
      return res.status(500).json({ error: "Failed to create donor" });
    }

    res.status(201).json(createdDonor);
  } catch (error) {
    res.status(500).json({ error: "Failed to create donor" });
  }
});

// Update a donor
router.put("/donors/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donor ID" });
    }

    const { name, contact, blood_group } = req.body;

    const existingDonor = getDonorById(id);
    if (!existingDonor) {
      return res.status(404).json({ error: "Donor not found" });
    }

    const updatedFields: Partial<typeof existingDonor> = {};

    if (name !== undefined) {
      updatedFields.name = name;
    }

    if (contact !== undefined) {
      updatedFields.contact = contact;
    }

    if (blood_group !== undefined) {
      updatedFields.blood_group = blood_group;
    }

    const success = updateDonor(id, updatedFields);

    if (!success) {
      return res.status(500).json({ error: "Failed to update donor" });
    }

    const updatedDonor = getDonorById(id);

    if (!updatedDonor) {
      return res.status(500).json({ error: "Failed to retrieve updated donor" });
    }

    res.json(updatedDonor);
  } catch (error) {
    res.status(500).json({ error: "Failed to update donor" });
  }
});

// Delete a donor
router.delete("/donors/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid donor ID" });
    }

    const success = deleteDonor(id);

    if (!success) {
      return res.status(404).json({ error: "Donor not found" });
    }

    res.json({ message: "Donor deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete donor" });
  }
});

// Search donors by blood type
router.get("/search", (req: Request, res: Response) => {
  try {
    const bloodGroup = req.query.blood_group as string;

    if (!bloodGroup) {
      return res.status(400).json({ error: "Blood group is required" });
    }

    // In a real app, we'd filter donors based on blood group
    // For now, just return all donors
    const donors = getAllDonors();

    // Record search result
    const donorIds = donors.map(donor => donor.id);
    donorIds.forEach(donorId => {
      insertSearchResult(donorId, bloodGroup, donors.length);
    });

    res.json(donors);
  } catch (error) {
    res.status(500).json({ error: "Failed to search donors" });
  }
});

// Get recent searches for a donor
router.get("/search/recent/:donorId", (req: Request, res: Response) => {
  try {
    const donorId = Number(req.params.donorId);
    if (isNaN(donorId)) {
      return res.status(400).json({ error: "Invalid donor ID" });
    }

    const searches = getRecentSearches(donorId);
    res.json(searches);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch recent searches" });
  }
});

