import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply TFA to login routes
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  // Check if TFA is enabled
  const tfaEnabled = process.env.TWO_FACTOR_AUTH_ENABLED;
  if (!tfaEnabled || tfaEnabled.toLowerCase() !== "true") {
    next();
    return;
  }

  // For now, we'll just pass through - actual implementation would require
  // checking user's TFA status and prompting if needed
  next();
}

