import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes/methods
  const protectedPaths = ["/company/drive", "/student/applications"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has appropriate role based on session or auth context
  // This is a simplified example - in reality, you'd extract roles from a token/session
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Define required roles for different endpoints
  const requiredRoles: Record<string, string[]> = {
    "/company/drive": ["company"],
    "/student/applications": ["student"]
  };

  // Find the correct path pattern
  let matchedPathPattern: keyof typeof requiredRoles | undefined = undefined;
  for (const [pattern, roles] of Object.entries(requiredRoles)) {
    if (req.path.startsWith(pattern)) {
      matchedPathPattern = pattern;
      break;
    }
  }

  if (!matchedPathPattern) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  // Check if user has the required role
  const allowedRoles = requiredRoles[matchedPathPattern];
  if (!allowedRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}

