import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to job-related routes
  const jobRoutes = ["/jobs", "/jobs/"];
  let isJobRoute = false;

  for (const route of jobRoutes) {
    if (req.path.startsWith(route)) {
      isJobRoute = true;
      break;
    }
  }

  // Skip validation for non-job routes
  if (!isJobRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For demonstration purposes, we'll assume manager role is required
  // In a real implementation, this should check actual authenticated user data
  const requiredRole = "manager";

  if (!userRole || userRole !== requiredRole) {
    res.status(403).json({ error: "Access denied. Manager role required." });
    return;
  }

  next();
}

