    typeof studentId !== "number" ||
    typeof hostelId !== "number" ||
    typeof menuItemId !== "number"
  ) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  try {
    // Check if vote already exists
    const existingVote = getVoteByStudentAndHostel(studentId, hostelId);

    if (existingVote) {
      // Update existing vote
      db.prepare(
        "UPDATE votes SET menu_item_id = ? WHERE student_id = ? AND hostel_id = ?"
      ).run(menuItemId, studentId, hostelId);
    } else {
      // Insert new vote
      insertVote(studentId, hostelId, menuItemId);
    }

    return res.status(201).json({ message: "Vote recorded successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to record vote" });
  }
});

// GET /hostel/:hostelId/results - Get voting results for a specific hostel
router.get("/hostel/:hostelId/results", (req: Request, res: Response) => {
  const hostelId = Number(req.params.hostelId);

  if (isNaN(hostelId)) {
    return res.status(400).json({ error: "Invalid hostel ID" });
  }

  try {
    const votes = getVotesByHostel(hostelId);

    // Aggregate results
    const result: Record<number, number> = {};
    votes.forEach(vote => {
      if (!result[vote.menu_item_id]) {
        result[vote.menu_item_id] = 0;
      }
      result[vote.menu_item_id]++;
    });

    return res.json(result);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch results" });
  }
});

// DELETE /vote - Delete a student's vote
router.delete("/vote", (req: Request, res: Response) => {
  const { studentId, hostelId } = req.body;

  // Validate input
  if (typeof studentId !== "number" || typeof hostelId !== "number") {
    return res.status(400).json({ error: "Invalid input data" });
  }

  try {
    const deletedRows = deleteVote(studentId, hostelId);

