import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to POST requests to the complaints endpoint
  if (req.method !== "POST" || !req.path.startsWith("/complaints")) {
    next();
    return;
  }

  // Check if the request has a body and contains an author ID
  const complaint = req.body;

  // If there's no body or no authorId, allow the request to proceed
  if (!complaint || typeof complaint.authorId === "undefined") {
    next();
    return;
  }

  // If the authorId is not zero, reject the request
  if (complaint.authorId !== 0) {
    res.status(403).json({ error: "Anonymous posting only allowed." });
    return;
  }

  // Allow the request to proceed if authorId is zero
  next();
}

