import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes/methods
  const protectedPaths = ["/study-groups", "/study-groups/"];
  const protectedMethods = ["POST", "PUT", "DELETE"];

  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !protectedMethods.includes(req.method)) {
    next();
    return;
  }

  // Check if user has required roles
  const userRoles = req.headers["x-user-roles"];
  const requiredRoles = ["student", "admin"];

  if (!userRoles || typeof userRoles !== "string") {
    res.status(403).json({ error: "Access denied: Missing or invalid roles" });
    return;
  }

  const userRoleSet = new Set(userRoles.split(","));
  const hasRequiredRole = requiredRoles.some(role => userRoleSet.has(role));

  if (!hasRequiredRole) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  next();
}

