  insertBooking
} from "../db/bookings-table";
import {
  getAllRooms,
  getRoomById
} from "../db/rooms-table";

export const router = Router();

// Get all bookings
router.get("/bookings", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    res.json(bookings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json(booking);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  try {
    const { roomId, startDate, endDate, bookerId } = req.body;

    // Validate required fields
    if (!roomId || !startDate || !endDate || !bookerId) {
      return res.status(400).json({ error: "Missing required fields: roomId, startDate, endDate, bookerId" });
    }

    // Check if room exists
    const room = getRoomById(Number(roomId));
    if (!room) {
      return res.status(404).json({ error: "Room not found" });
    }

    // Check if the booking overlaps with existing bookings
    const existingBookings = getAllBookings().filter(booking => {
      const bookingStart = new Date(booking.startDate);
      const bookingEnd = new Date(booking.endDate);
      const newStart = new Date(startDate);
      const newEnd = new Date(endDate);

      return !(newEnd <= bookingStart || newStart >= bookingEnd);
    });

    if (existingBookings.length > 0) {
      return res.status(409).json({ error: "This room is already booked during the specified time" });
    }

    // Insert the new booking
    const newBookingId = insertBooking(
      Number(roomId),
      startDate,
      endDate,
      Number(bookerId)
    );

    // Fetch the created booking to send back
    const createdBooking = getBookingById(newBookingId);

    if (!createdBooking) {
      return res.status(500).json({ error: "Failed to retrieve created booking" });
    }

    res.status(201).json(createdBooking);
  } catch (error) {
    res.status(500).json({ error: "Failed to create booking" });
  }
});

// Delete a booking
router.delete("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const deleted = deleteBooking(id);

    if (!deleted) {
      return res.status(404).json({ error: "Booking not found" });
    }

    res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete booking" });
  }
});
